<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipAllowController;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipListController;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipCreateController;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipRetrieveController;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipUpdateController;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driver\Rest\UserGroupMembershipDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Service\Visibility\UserGroupMembershipRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driven\UserGroupMembershipReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driven\UserGroupMembershipWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipReadGateway;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipWriteGateway;

class UserGroupMembershipPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserGroupMembershipReadGateway::class] = \DI\autowire(UserGroupMembershipReadRepositoryAdapter::class);
        $def[UserGroupMembershipWriteGateway::class] = \DI\autowire(UserGroupMembershipWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/user-group-membership', [$this, 'setRoutesForUserGroupMembership']);
        $collector->group('/api/me/acl/access/user-group-membership', [$this, 'setRoutesForUserGroupMembershipAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(UserGroupMembershipRestrictFilterToVisibility::class, TenantAccesible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("user-group-membership", "list", "READ");
            $handler->registerResourceAction("user-group-membership", "create", "WRITE");
            $handler->registerResourceAction("user-group-membership", "retrieve", "READ");
            $handler->registerResourceAction("user-group-membership", "update", "WRITE");
            $handler->registerResourceAction("user-group-membership", "delete", "WRITE");

            $handler->registerResourceAttribute("user-group-membership", "user", "MANAGE");
            $handler->registerResourceAttribute("user-group-membership", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("user-group-membership", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("user-group-membership", "groups", "MANAGE");
            $handler->registerResourceAttribute("user-group-membership", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForUserGroupMembershipAcl(RouteCollectorProxy $userGroupMembershipGroup): void
    {
        $userGroupMembershipGroup->get('', [UserGroupMembershipAllowController::class, 'genericAllow']);
        $userGroupMembershipGroup->get('/{uid}', [UserGroupMembershipAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForUserGroupMembership(RouteCollectorProxy $userGroupMembershipGroup): void
    {
        $userGroupMembershipGroup->get('', [UserGroupMembershipListController::class, 'list']);
        $userGroupMembershipGroup->post('', [UserGroupMembershipCreateController::class, 'create']);
        $userGroupMembershipGroup->get('/{uid}', [UserGroupMembershipRetrieveController::class, 'retrieve']);
        $userGroupMembershipGroup->put('/{uid}', [UserGroupMembershipUpdateController::class, 'update']);
        $userGroupMembershipGroup->delete('/{uid}', [UserGroupMembershipDeleteController::class, 'delete']);
        $userGroupMembershipGroup->delete('', [UserGroupMembershipDeleteController::class, 'deleteAllForQuery']);
        $userGroupMembershipGroup->get('/~/delete-status/{uid}', [UserGroupMembershipDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
